# Grounding-rule review of terms.json (TASKS.md #24), decided 2026-10-30: hybrid.
# A plain definition stays a definition. Any entry that asserts a number, a comparison,
# a frequency ("usually", "most") or a named system gets a source here or is rewritten
# so it no longer asserts. terms.json is left as the pre-review draft; build_glossary.py
# applies these overrides on top of it.
#
# term: {"m": new meaning, "w": new when-it-comes-up, "src": [(label, url or None)]}
# Keys omitted keep the draft text. Numbers below were checked against the source on
# 2026-10-30 (abstracts / intros), except books, which are cited for the method.

KOHAVI = ("Kohavi, Tang & Xu, Trustworthy Online Controlled Experiments (Cambridge, 2020)", None)
TREFETHEN = ("Trefethen & Bau, Numerical Linear Algebra (SIAM, 1997)", None)

